import { StringColumn, IntegerColumn, BooleanColumn } from '@servicenow/sdk/core'
import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'

/**
 * Test flow for SetFlowVariables with complex inline scripts and datapills
 * Tests that inline scripts and datapills work together without interference
 */
export const setFlowVariablesInlineScriptComplex = Flow(
    {
        $id: Now.ID['set-flow-variables-inline-script-complex'],
        name: 'SetFlowVariables Inline Script Complex Test',
        description: 'Test SetFlowVariables with mix of inline scripts, datapills, and literals',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            // Datapill variables
            incidentNumber: StringColumn({
                label: 'Incident Number',
                mandatory: false,
            }),
            priority: IntegerColumn({
                label: 'Priority',
                mandatory: false,
            }),
            // Inline script variables
            computedPriority: IntegerColumn({
                label: 'Computed Priority',
                mandatory: false,
            }),
            enrichedDescription: StringColumn({
                label: 'Enriched Description',
                mandatory: false,
            }),
            // Literal variable
            status: StringColumn({
                label: 'Status',
                mandatory: false,
            }),
            // Template expression with datapill
            summary: StringColumn({
                label: 'Summary',
                mandatory: false,
            }),
            // Inline script accessing fd_data
            triggerInfo: StringColumn({
                label: 'Trigger Info',
                mandatory: false,
            }),
            // Mixed - inline script that uses fd_data to access trigger
            dynamicMessage: StringColumn({
                label: 'Dynamic Message',
                mandatory: false,
            }),
            isHighPriority: BooleanColumn({
                label: 'Is High Priority',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['set-flow-vars-inline-complex-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Execute an action to get outputs for testing
        const lookupResult = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup-incident-for-vars'],
                annotation: 'Look up incident record',
            },
            {
                table: 'incident',
                conditions: wfa.dataPill(params.trigger.current.sys_id, 'reference'),
            }
        )

        // Test 1: SetFlowVariables with mixed inline scripts, datapills, and literals
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-mixed-values'],
                annotation: 'Set variables with mixed value types',
            },
            params.flowVariables,
            {
                // Pure datapill - should be converted to {{trigger.current.number}}
                incidentNumber: wfa.dataPill(params.trigger.current.number, 'string'),

                // Pure datapill - should be converted to {{trigger.current.priority}}
                priority: wfa.dataPill(params.trigger.current.priority, 'integer'),

                // Pure inline script - should have scriptActive: true
                computedPriority: wfa.inlineScript('return Math.floor(Math.random() * 5) + 1'),

                // Pure inline script accessing fd_data
                enrichedDescription: wfa.inlineScript(
                    "return 'Enhanced: ' + (fd_data.trigger.current.short_description || 'N/A')"
                ),

                // Pure literal - should remain as string
                status: 'processing',

                // Template expression with datapill - should resolve datapill inside template
                summary: `Incident ${wfa.dataPill(params.trigger.current.number, 'string')} created with priority ${wfa.dataPill(params.trigger.current.priority, 'integer')}`,

                // Inline script with more complex fd_data access
                triggerInfo: wfa.inlineScript(
                    "return 'Table: ' + fd_data.trigger.current.sys_class_name + ', Record: ' + fd_data.trigger.current.sys_id"
                ),

                // Inline script with conditional logic accessing fd_data
                dynamicMessage: wfa.inlineScript(`
                    var priority = fd_data.trigger.current.priority;
                    if (priority == 1) return 'CRITICAL - Immediate attention required';
                    if (priority == 2) return 'HIGH - Urgent action needed';
                    if (priority == 3) return 'MODERATE - Address soon';
                    return 'LOW - Standard processing';
                `),

                // Inline script returning boolean based on fd_data
                isHighPriority: wfa.inlineScript('return fd_data.trigger.current.priority <= 2'),
            }
        )

        // Test 2: SetFlowVariables with action output datapill
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-action-output'],
                annotation: 'Set variables with action output datapills',
            },
            params.flowVariables,
            {
                // Action output datapill - should be converted to {{<action-uuid>.*}}
                incidentNumber: wfa.dataPill(lookupResult.Record, 'reference'),
            }
        )

        // Test 3: SetFlowVariables with flow variable reference (self-reference)
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-self-reference'],
                annotation: 'Set variables referencing other flow variables',
            },
            params.flowVariables,
            {
                // Reference to another flow variable - should be {{flow_variable.status}}
                summary: wfa.dataPill(params.flowVariables.status, 'string'),

                // Inline script accessing flow variable via fd_data
                enrichedDescription: wfa.inlineScript(
                    "return 'Status: ' + fd_data.flowVariables.status + ' | Priority: ' + fd_data.flowVariables.priority"
                ),
            }
        )
    }
)
